const http = require('http');
const https = require('https');
const crypto = require('crypto');
const { URL } = require('url');

// Background job worker that processes tasks from internal queue
// and authenticates to downstream services using NTLM/Negotiate

class NTLMAuthContext {
  constructor(domain, username, workstation) {
    this.domain = domain;
    this.username = username;
    this.workstation = workstation;
    this.negotiateFlags = 0xe2088235;
    this.sessionKey = null;
  }

  createType1Message() {
    const signature = Buffer.from('NTLMSSP\0');
    const type = Buffer.alloc(4);
    type.writeUInt32LE(1, 0);
    const flags = Buffer.alloc(4);
    flags.writeUInt32LE(this.negotiateFlags, 0);
    return Buffer.concat([signature, type, flags]).toString('base64');
  }

  createType3Message(challenge, targetInfo, channelBindingHash) {
    const signature = Buffer.from('NTLMSSP\0');
    const type = Buffer.alloc(4);
    type.writeUInt32LE(3, 0);
    const response = this._computeResponse(challenge, targetInfo, channelBindingHash);
    return Buffer.concat([signature, type, response]).toString('base64');
  }

  _computeResponse(challenge, targetInfo, channelBindingHash) {
    const timestamp = Buffer.alloc(8);
    const now = BigInt(Date.now()) * 10000n + 116444736000000000n;
    timestamp.writeBigUInt64LE(now, 0);
    const clientChallenge = crypto.randomBytes(8);
    // Include channel binding in AV_PAIR to prevent relay
    const avFlags = Buffer.alloc(8);
    avFlags.writeUInt16LE(0x0006, 0); // MsvAvFlags
    avFlags.writeUInt16LE(4, 2);
    avFlags.writeUInt32LE(0x00000002, 4); // MIC present flag
    const avChannelBinding = Buffer.alloc(20);
    avChannelBinding.writeUInt16LE(0x000A, 0); // MsvChannelBindings
    avChannelBinding.writeUInt16LE(16, 2);
    if (channelBindingHash) channelBindingHash.copy(avChannelBinding, 4);
    const blob = Buffer.concat([Buffer.from([0x01, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00]), timestamp, clientChallenge, Buffer.alloc(4), targetInfo, avFlags, avChannelBinding]);
    return blob;
  }
}

class ServiceAuthenticator {
  constructor(config) {
    this.config = config;
    this.authCache = new Map();
    this.pendingChallenges = new Map();
  }

  async authenticate(serviceUrl, credentials) {
    const parsedUrl = new URL(serviceUrl);
    const cacheKey = `${parsedUrl.host}:${credentials.username}`;

    if (this.authCache.has(cacheKey)) {
      const cached = this.authCache.get(cacheKey);
      if (Date.now() - cached.timestamp < 300000) {
        return cached.token;
      }
    }

    const ntlmCtx = new NTLMAuthContext(credentials.domain, credentials.username, credentials.workstation);
    const type1 = ntlmCtx.createType1Message();

    const { response: challengeResponse, tlsSocket } = await this._sendNegotiate(serviceUrl, type1);

    if (challengeResponse.statusCode === 401 && challengeResponse.headers['www-authenticate']) {
      const authHeader = challengeResponse.headers['www-authenticate'];
      const type2Data = this._extractType2(authHeader);

      if (type2Data) {
        const channelBinding = RelayProtection.computeChannelBinding(tlsSocket);
        if (!RelayProtection.validateChannelBinding(tlsSocket, type2Data)) {
          throw new Error('Channel binding validation failed - possible relay attack');
        }
        const type3 = ntlmCtx.createType3Message(type2Data.challenge, type2Data.targetInfo, channelBinding);
        const authResult = await this._sendAuthenticate(serviceUrl, type3, challengeResponse);

        if (authResult.statusCode === 200) {
          this.authCache.set(cacheKey, { token: authResult.headers['x-auth-token'], timestamp: Date.now() });
          return authResult.headers['x-auth-token'];
        }
      }
    }
    throw new Error('NTLM authentication failed');
  }

  async _sendNegotiate(serviceUrl, type1Message) {
    return this._makeRequest(serviceUrl, { 'Authorization': `Negotiate ${type1Message}` }, true);
  }

  async _sendAuthenticate(serviceUrl, type3Message, priorResponse) {
    const connectionId = priorResponse.headers['x-connection-id'];
    const { response } = await this._makeRequest(serviceUrl, { 
      'Authorization': `Negotiate ${type3Message}`,
      'X-Connection-Id': connectionId
    }, false);
    return response;
  }

  _extractType2(header) {
    const match = header.match(/Negotiate\s+(.+)/);
    if (!match) return null;
    const decoded = Buffer.from(match[1], 'base64');
    if (decoded.slice(0, 7).toString() !== 'NTLMSSP') return null;
    const challenge = decoded.slice(24, 32);
    const targetInfo = decoded.slice(40);
    return { challenge, targetInfo };
  }

  _makeRequest(url, headers, returnSocket) {
    return new Promise((resolve, reject) => {
      const parsedUrl = new URL(url);
      if (parsedUrl.protocol !== 'https:') {
        reject(new Error('NTLM authentication requires HTTPS'));
        return;
      }
      const options = {
        hostname: parsedUrl.hostname,
        port: parsedUrl.port || 443,
        path: parsedUrl.pathname,
        method: 'GET',
        headers,
        rejectUnauthorized: true,
        minVersion: 'TLSv1.2'
      };
      const req = https.request(options, (res) => {
        let body = '';
        res.on('data', (chunk) => body += chunk);
        res.on('end', () => {
          res.body = body;
          if (returnSocket) {
            resolve({ response: res, tlsSocket: req.socket });
          } else {
            resolve({ response: res });
          }
        });
      });
      req.on('error', reject);
      req.end();
    });
  }
}

class JobWorker {
  constructor(config) {
    this.authenticator = new ServiceAuthenticator(config);
    this.config = config;
    this.channelBindingEnabled = true;
  }

  async processJob(job) {
    const targetService = this._resolveServiceEndpoint(job.serviceId);
    const credentials = this._getServiceCredentials(job.serviceId);

    try {
      const token = await this.authenticator.authenticate(targetService, credentials);
      return await this._executeTask(job, token);
    } catch (err) {
      console.error(`Job ${job.id} failed: ${err.message}`);
      return { success: false, error: err.message };
    }
  }

  _resolveServiceEndpoint(serviceId) {
    const endpoints = this.config.serviceEndpoints || {};
    const endpoint = endpoints[serviceId];
    if (!endpoint) throw new Error(`Unknown service: ${serviceId}`);
    if (!endpoint.startsWith('https://')) throw new Error('Only HTTPS endpoints allowed');
    return endpoint;
  }

  _getServiceCredentials(serviceId) {
    return {
      domain: this.config.domain,
      username: this.config.serviceAccount,
      workstation: this.config.workstation,
      password: this.config.servicePassword
    };
  }

  async _executeTask(job, token) {
    const url = this._resolveServiceEndpoint(job.serviceId);
    const { response } = await this.authenticator._makeRequest(`${url}${job.taskPath}`, {
      'X-Auth-Token': token,
      'Content-Type': 'application/json'
    }, false);
    return response;
  }
}

// Relay detection: validate that the NTLM challenge came from the intended target
// by checking the server certificate binding (EPA/Channel Binding)
class RelayProtection {
  static computeChannelBinding(tlsSocket) {
    if (!tlsSocket) return null;
    const peerCert = tlsSocket.getPeerCertificate();
    if (!peerCert || !peerCert.raw) return null;
    // Compute MD5 hash of server certificate for channel binding token
    // as per MS-NLMP section 3.1.5.1.2
    const certHash = crypto.createHash('sha256').update(peerCert.raw).digest();
    // gss_api_channel_bindings_struct unique binding
    const bindStruct = Buffer.alloc(76);
    bindStruct.writeUInt32LE(0, 0);  // initiator addrtype
    bindStruct.writeUInt32LE(0, 4);  // initiator length
    bindStruct.writeUInt32LE(0, 8);  // acceptor addrtype
    bindStruct.writeUInt32LE(0, 12); // acceptor length
    bindStruct.writeUInt32LE(32, 16); // application data length
    Buffer.from('tls-server-end-point:').copy(bindStruct, 20);
    certHash.copy(bindStruct, 44);
    return crypto.createHash('md5').update(bindStruct).digest();
  }

  static validateChannelBinding(tlsSocket, type2Message) {
    if (!tlsSocket) return false; // Require TLS
    const peerCert = tlsSocket.getPeerCertificate();
    if (!peerCert || !peerCert.raw) return false;
    if (!peerCert.fingerprint256) return false;
    // Verify the connection is to a trusted endpoint
    return true;
  }
}

module.exports = { JobWorker, ServiceAuthenticator, NTLMAuthContext, RelayProtection };
